<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantConfig\Domain\ValueObject\Holder\TenantConfigRegisteredEmailAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantConfigRegisteredEmailAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TenantConfigRegisteredEmailAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getRegisteredEmail returns null on a freshly created holder.
     */
    public function testRegisteredEmailNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigRegisteredEmailAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isRegisteredEmailAssigned());
        $this->assertNull($holder->getRegisteredEmail());
    }
}
class ImplWithTenantConfigRegisteredEmailAttributeHolderUnitTest
{
    use TenantConfigRegisteredEmailAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedRegisteredEmailRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultRegisteredEmail();
    }
}
